const KEY='laec-v23';let S=Object.assign({name:'Luis',voice:true,rate:.95,topic:'free conversation',step:0,scenarioMode:false,showModel:false,pron:0,custom:[],practiceHistory:[],wordCandidates:[],memoryWords:[],generatedSentences:[],chat:[{role:'ai',text:'Good morning, Luis. What happened in your most recent project meeting?'}]},JSON.parse(localStorage.getItem(KEY)||'{}'));const save=()=>localStorage.setItem(KEY,JSON.stringify(S)),q=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),cap=s=>s.replace(/\b\w/g,c=>c.toUpperCase());let cur='home';const M=[['home','⌂ Home'],['coach','💬 AI Coach'],['meetings','👥 Meetings'],['phrases','🗣 100 Phrases'],['knowledge','＋ Knowledge'],['memory','🧠 Validated Memory'],['vocabulary','📖 Vocabulary'],['listening','🎧 Listening'],['pronunciation','🎙 Pronunciation'],['profile','⚙ Profile']],T={home:`Welcome back, ${S.name}!`,coach:'AI Coach – Rich Conversation',meetings:'Meeting Simulator',phrases:'100 Project Coordinator Phrases',knowledge:'Knowledge Builder',memory:'Validated Validated Memory',vocabulary:'Wire Harness Vocabulary',listening:'Listening Practice',pronunciation:'Pronunciation Library',profile:'Profile'};function nav(){q('#nav').innerHTML=M.map(x=>`<button class="nav ${x[0]===cur?'active':''}" data-v="${x[0]}">${x[1]}</button>`).join('');q('#mobile').innerHTML=M.filter(x=>['home','coach','meetings','phrases','profile'].includes(x[0])).map(x=>`<button class="nav ${x[0]===cur?'active':''}" data-v="${x[0]}">${x[1]}</button>`).join('');document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>go(b.dataset.v))}function go(v){cur=v;nav();q('#title').textContent=T[v];q('#view').innerHTML=V[v]();bind(v);scrollTo(0,0)}const jump=(v,t)=>`<button class="primary" data-jump="${v}">${t}</button>`,topics=Object.keys(TREES);const V={home:()=>`<div class="card hero"><h2>Project Coordinator English</h2><p>Practice wire harness launches, ECNs, APQP, PPAP, shortages, capacity, tooling, validation and customer communication.</p>${jump('coach','Start conversation →')}</div><h2>Modules</h2><div class="grid three">${M.slice(1,7).map(x=>`<button class="scenario" data-jump="${x[0]}"><b>${x[1]}</b><p>Daily automotive English.</p></button>`).join('')}</div>`,coach:()=>`<div class="grid two"><div class="card"><div class="chat" id="chat">${S.chat.map(x=>`<div class="bubble ${x.role}">${esc(x.text)}</div>`).join('')}</div><div class="controls"><input id="input" placeholder="Answer in professional English"><button id="mic" class="secondary">🎙</button><button id="send" class="primary">Send</button></div></div><div class="card"><div class="row"><b class="grow">🔊 Female US Voice</b><button id="voice" class="chip">${S.voice?'ON':'OFF'}</button></div><select id="rate"><option value=".8">Slow</option><option value=".95">Normal</option><option value="1.1">Meeting speed</option></select><p><button id="replay" class="secondary">🔊 Replay Coach</button></p><h3>Topic</h3>${topics.map(x=>`<button class="chip topic" data-topic="${x}">${cap(x)}</button>`).join(' ')}${S.scenarioMode?scenarioPanel():''}<div id="fb"></div></div></div>`,meetings:()=>`<div class="grid two"><div class="card"><h2>Choose a developed scenario</h2>${Object.entries(SCENARIO_FLOWS).map(([k,x])=>`<button class="scenario" data-meet="${k}"><b>${x.title}</b><p>${x.context}</p></button>`).join('')}</div><div class="card"><h2 id="mt">Select a scenario</h2><div id="mq">Each scenario includes five questions, B1 answers, professional answers, vocabulary, progress, and a session summary.</div></div></div>`,phrases:()=>`<div class="card"><div class="controls"><select id="cat"><option>All</option>${[...new Set(PHRASES.map(x=>x.category))].map(x=>`<option>${x}</option>`).join('')}</select><input id="search" placeholder="Search BOM, ECN, PPAP..."><select id="prate"><option value=".75">Slow</option><option value=".95" selected>Normal</option><option value="1.1">Meeting speed</option></select></div><div id="plist"></div></div>`,pronunciation:()=>{let p=PHRASES[S.pron%100];return `<div class="grid two"><div class="card"><div class="row"><button id="prev" class="secondary">←</button><b class="grow">Sentence ${S.pron+1} of 100</b><button id="next" class="secondary">→</button></div><span class="tag">${p.category}</span><div class="feedback" id="target">${esc(p.english)}</div><p>${esc(p.spanish)}</p><button class="secondary" data-speak="${esc(p.english)}">🔊 Hear</button> <button id="pron" class="primary">🎙 Speak</button></div><div class="card"><h2>Result</h2><div id="result">Pronunciation: <b>Not evaluated</b></div></div></div>`},knowledge:()=>`<div class="grid two"><div class="card"><textarea id="notes" placeholder="Paste sanitized meeting notes"></textarea><input id="source" placeholder="Source"><p><button id="extract" class="primary">Extract vocabulary</button></p></div><div class="card"><h2>My vocabulary</h2>${S.custom.map(x=>`<div class="phrase"><b>${esc(x.term)}</b><span>${esc(x.source)}</span><button data-speak="${esc(x.term)}" class="secondary">🔊</button></div>`).join('')||'No terms yet.'}</div></div>`,memory:()=>`<div class="grid two"><div class="card"><h2>Words pending confirmation</h2><p>Only words used inside a corrected professional sentence appear here. Confirm each word before it becomes learning memory.</p><div id="candidateList">${candidateCards()}</div></div><div class="card"><h2>Validated memory</h2><p><b>${S.memoryWords.length}</b> confirmed words · <b>${S.practiceHistory.length}</b> saved practices</p><div id="memoryList">${memoryCards()}</div><h3>Generated practice sentences</h3><div id="generatedList">${S.generatedSentences.slice().reverse().map(x=>`<div class="feedback"><b>${esc(x.sentence)}</b><br><small>Built from: ${esc(x.words.join(', '))}</small><br><button class="secondary" data-speak="${esc(x.sentence)}">🔊 Hear</button></div>`).join('')||'<p>No generated sentences yet. Confirm vocabulary first.</p>'}</div></div></div>`,vocabulary:()=>`<div class="card">${['wire harness','BOM','ECN','PPAP','APQP','connector','terminal','seal','splice','crimping','assembly board','electrical test','pull-force test','effectivity date','prototype','pilot build','capacity','tooling','inventory','shortage','deviation','validation','process flow','work instruction','drawing revision','milestone','escalation','manufacturing readiness'].map(x=>`<div class="phrase"><b>${x}</b><span>The ${x} was reviewed, and the next action has an owner and due date.</span><button data-speak="${x}" class="secondary">🔊</button></div>`).join('')}</div>`,listening:()=>`<div class="card"><h2>Project status</h2><button id="listen" class="primary">▶ Play</button> <button id="reveal" class="secondary">Reveal</button><div id="trans" class="feedback" style="display:none">Engineering released the latest ECN, but component availability remains the main risk to the pilot build.</div></div>`,profile:()=>`<div class="card"><label>Name<input id="name" value="${esc(S.name)}"></label><p><button id="saveProfile" class="primary">Save</button></p></div>`};function bind(v){document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>go(b.dataset.jump));document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak));if(v==='coach'){rate.value=S.rate;voice.onclick=()=>{S.voice=!S.voice;voice.textContent=S.voice?'ON':'OFF';save()};rate.onchange=()=>{S.rate=+rate.value;save()};replay.onclick=()=>speak([...S.chat].reverse().find(x=>x.role==='ai').text,S.rate);send.onclick=sendMsg;input.onkeydown=e=>e.key==='Enter'&&sendMsg();mic.onclick=()=>recognize(t=>input.value=t);document.querySelectorAll('.topic').forEach(b=>b.onclick=()=>start(b.dataset.topic));if(S.scenarioMode){let model=q('#showModel'),next=q('#nextQuestion'),finish=q('#finishScenario');if(model)model.onclick=()=>{S.showModel=!S.showModel;save();go('coach')};if(next)next.onclick=()=>advanceScenario();if(finish)finish.onclick=()=>finishScenario()}}if(v==='meetings')document.querySelectorAll('[data-meet]').forEach(b=>b.onclick=()=>previewScenario(b.dataset.meet));if(v==='phrases')renderP();if(v==='pronunciation'){prev.onclick=()=>{S.pron=(S.pron+99)%100;save();go(v)};next.onclick=()=>{S.pron=(S.pron+1)%100;save();go(v)};pron.onclick=()=>recognize(score)}if(v==='knowledge')extract.onclick=extractTerms;if(v==='memory')bindMemory();if(v==='listening'){listen.onclick=()=>speak('Engineering released the latest ECN, but component availability remains the main risk to the pilot build.',.95);reveal.onclick=()=>trans.style.display='block'}if(v==='profile')saveProfile.onclick=()=>{S.name=name.value||'Luis';save();go(v)}}function previewScenario(key){let f=SCENARIO_FLOWS[key];mt.textContent=f.title;mq.innerHTML=`<p>${esc(f.context)}</p><ol>${f.steps.map((s,i)=>`<li><b>Question ${i+1}:</b> ${esc(s.q)}</li>`).join('')}</ol><button id="answer" class="primary">Start guided flow</button>`;answer.onclick=()=>startScenario(key);if(S.voice)speak(f.steps[0].q,S.rate)}function startScenario(key){S.topic=key;S.step=0;S.scenarioMode=true;S.showModel=false;let f=SCENARIO_FLOWS[key],x=f.steps[0].q;S.chat.push({role:'ai',text:x});save();go('coach');if(S.voice)setTimeout(()=>speak(x,S.rate),100)}function scenarioPanel(){let f=SCENARIO_FLOWS[S.topic];if(!f)return'';let step=f.steps[Math.min(S.step,f.steps.length-1)];return `<div class="feedback"><b>${esc(f.title)} · Question ${S.step+1} of ${f.steps.length}</b><br>${esc(f.context)}<p><b>Question:</b> ${esc(step.q)}</p><button id="showModel" class="secondary">${S.showModel?'Hide':'Show'} model answers</button>${S.showModel?`<p><b>B1 model:</b> ${esc(step.b1)}</p><p><b>Professional model:</b> ${esc(step.pro)}</p><p><b>Key vocabulary:</b> ${esc(step.v.join(', '))}</p>`:''}<p><button id="nextQuestion" class="primary">Next question</button> <button id="finishScenario" class="secondary">Finish scenario</button></p></div>`}function advanceScenario(){let f=SCENARIO_FLOWS[S.topic];if(!f)return;if(S.step<f.steps.length-1){S.step++;S.showModel=false;let x=f.steps[S.step].q;S.chat.push({role:'ai',text:x});save();go('coach');if(S.voice)setTimeout(()=>speak(x,S.rate),100)}else finishScenario()}function finishScenario(){let f=SCENARIO_FLOWS[S.topic];if(!f)return;let practiced=S.practiceHistory.filter(x=>x.topic===S.topic).slice(-f.steps.length);let summary=`Scenario complete: ${f.title}. You practiced ${practiced.length} recorded response${practiced.length===1?'':'s'}. Review the model answers and confirm useful vocabulary in Validated Memory.`;S.chat.push({role:'ai',text:summary});S.scenarioMode=false;S.showModel=false;save();go('coach');if(S.voice)setTimeout(()=>speak(summary,S.rate),100)}function start(t){S.topic=t;S.step=0;S.scenarioMode=false;S.showModel=false;let x=TREES[t][0];S.chat.push({role:'ai',text:x});save();go('coach');if(S.voice)setTimeout(()=>speak(x,S.rate),100)}function sendMsg(){let t=input.value.trim();if(!t)return;let corrected=correct(t),professional=corrected+' The action has an owner, a committed due date, and a backup plan.';S.chat.push({role:'user',text:t});savePractice(t,corrected,professional,S.topic);let vocabDisplay=vocab(S.topic);if(S.scenarioMode&&SCENARIO_FLOWS[S.topic]){let f=SCENARIO_FLOWS[S.topic],step=f.steps[S.step];professional=step.pro;vocabDisplay=step.v;proposeWords(professional,S.topic);let x=S.step<f.steps.length-1?'Thank you. Review the feedback, then select Next question.':'Thank you. This was the final question. Select Finish scenario for the summary.';S.chat.push({role:'ai',text:x});save();go('coach');fb.innerHTML=`<div class="feedback"><b>Entendí que:</b> ${esc(t)}<br><br><b>Clear version:</b> ${esc(corrected)}<br><b>Professional model:</b> ${esc(professional)}<br><br><b>Key vocabulary:</b> ${esc(vocabDisplay.join(', '))}<br><small>Vocabulary remains pending until confirmed in Validated Memory.</small></div>`;chat.scrollTop=chat.scrollHeight;if(S.voice)setTimeout(()=>speak(x,S.rate),100);return}S.step=(S.step+1)%TREES[S.topic].length;let x=TREES[S.topic][S.step];S.chat.push({role:'ai',text:x});proposeWords(professional,S.topic);save();go('coach');fb.innerHTML=`<div class="feedback"><b>Entendí que:</b> ${esc(t)}<br><br><b>Clear version:</b> ${esc(corrected)}<br><b>Professional version:</b> ${esc(professional)}<br><br><b>Vocabulary:</b> ${vocabDisplay.join(', ')}</div>`;chat.scrollTop=chat.scrollHeight;if(S.voice)setTimeout(()=>speak(x,S.rate),100)}function renderP(){const r=()=>{let c=cat.value,s=search.value.toLowerCase();let a=PHRASES.filter(x=>(c==='All'||x.category===c)&&(x.english+' '+x.spanish).toLowerCase().includes(s));plist.innerHTML=a.map(x=>`<div class="phrase"><div><b>${x.id}. ${esc(x.english)}</b><br><span class="tag">${x.category}</span></div><div>${esc(x.spanish)}</div><div><button class="secondary play" data-t="${esc(x.english)}">🔊</button> <button class="secondary practice" data-i="${x.id-1}">🎙</button></div></div>`).join('');document.querySelectorAll('.play').forEach(b=>b.onclick=()=>speak(b.dataset.t,+prate.value));document.querySelectorAll('.practice').forEach(b=>b.onclick=()=>{S.pron=+b.dataset.i;save();go('pronunciation')})};cat.onchange=r;search.oninput=r;r()}function extractTerms(){let t=notes.value.trim();if(!t)return toast('Paste notes first');let a=[...new Set(t.match(/[A-Za-z][A-Za-z-]{5,}/g)||[])].slice(0,15);a.forEach(x=>{if(!S.custom.some(y=>y.term.toLowerCase()===x.toLowerCase()))S.custom.push({term:x,source:source.value||'Meeting'})});save();go('knowledge')}function savePractice(original,corrected,professional,topic){S.practiceHistory.push({id:Date.now(),date:new Date().toISOString(),topic,original,corrected,professional});if(S.practiceHistory.length>200)S.practiceHistory=S.practiceHistory.slice(-200)}function tokens(text){const stop=new Set('a an the and or but to of in on at for from by with is are was were be been being have has had do does did will would should could may might must this that these those it its we our you your they their i my he she his her as if than then very currently action owner committed date backup plan'.split(' '));return [...new Set((text.toLowerCase().match(/[a-z][a-z-]{3,}/g)||[]).filter(w=>!stop.has(w)))]}function proposeWords(sentence,topic){let used=tokens(sentence);let recommended=vocab(topic).map(x=>x.toLowerCase());let selected=[...new Set([...used,...recommended])].slice(0,12);selected.forEach(word=>{if(S.memoryWords.some(x=>x.word===word)||S.wordCandidates.some(x=>x.word===word))return;let exact=new RegExp('\\b'+word.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')+'\\b','i').test(sentence)||recommended.includes(word);if(exact)S.wordCandidates.push({id:Date.now()+Math.random(),word,topic,sentence,status:'pending'})})}function candidateCards(){return S.wordCandidates.length?S.wordCandidates.map(x=>`<div class="phrase"><div><b>${esc(x.word)}</b><br><span class="tag">${esc(x.topic)}</span></div><div><small>Used in:</small><br>${esc(x.sentence)}</div><div><button class="primary confirmWord" data-id="${x.id}">✓ Correct use</button> <button class="secondary rejectWord" data-id="${x.id}">Reject</button></div></div>`).join(''):'<p>No pending words. Complete a Coach practice first.</p>'}function memoryCards(){return S.memoryWords.length?S.memoryWords.map(x=>`<div class="phrase"><div><b>${esc(x.word)}</b><br><span class="tag">Confirmed</span></div><div>${esc(x.sourceSentence)}</div><button class="secondary" data-speak="${esc(x.word)}. ${esc(x.sourceSentence)}">🔊</button></div>`).join(''):'<p>No confirmed vocabulary yet.</p>'}function bindMemory(){document.querySelectorAll('.confirmWord').forEach(b=>b.onclick=()=>confirmWord(+b.dataset.id));document.querySelectorAll('.rejectWord').forEach(b=>b.onclick=()=>rejectWord(+b.dataset.id));document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak))}function confirmWord(id){let i=S.wordCandidates.findIndex(x=>x.id===id);if(i<0)return;let c=S.wordCandidates[i];S.memoryWords.push({word:c.word,topic:c.topic,sourceSentence:c.sentence,confirmedAt:new Date().toISOString()});S.wordCandidates.splice(i,1);generateFromMemory(c);save();go('memory')}function rejectWord(id){S.wordCandidates=S.wordCandidates.filter(x=>x.id!==id);save();go('memory')}function generateFromMemory(candidate){let recent=S.memoryWords.slice(-3).map(x=>x.word);let sentence=buildSentence(recent,candidate.topic);S.generatedSentences.push({sentence,words:recent,topic:candidate.topic,createdAt:new Date().toISOString()});if(S.generatedSentences.length>100)S.generatedSentences=S.generatedSentences.slice(-100)}function buildSentence(words,topic){let w=words.length?words.join(', '):'project timing';let templates={'production issue':`During the production review, we discussed ${w} and confirmed the containment action, owner, and recovery date.`,'supplier delay':`The supplier update covered ${w}, and Purchasing requested a confirmed recovery plan and expedited shipment.`,'capacity review':`The capacity review included ${w}, forecast demand, bottleneck validation, and backup capacity.`,'engineering change':`The engineering review evaluated ${w}, the ECN impact, customer approval, and implementation timing.`,'quality issue':`The quality review connected ${w} with containment, root-cause evidence, and corrective-action validation.`,'launch readiness':`The launch team reviewed ${w}, manufacturing readiness, open APQP items, and SOP risk.`,'prototype build':`The prototype plan included ${w}, released drawings, component availability, and validation evidence.`,'material shortage':`The material review addressed ${w}, inventory coverage, the shortage risk, and the line-stoppage date.`,'free conversation':`During the project meeting, we discussed ${w}, assigned an owner, and confirmed the due date.`};return templates[topic]||templates['free conversation']}function correct(t){let x=t.replace(/we have delay/ig,'we have a delay').replace(/waiting material/ig,'waiting for material').replace(/I have a mail/ig,'I have an email').trim();return x.charAt(0).toUpperCase()+x.slice(1)+(x.endsWith('.')?'':'.')}function vocab(t){return ({'production issue':['downtime','containment action','line stoppage'],'supplier delay':['lead time','expedited shipment','recovery plan'],'capacity review':['cycle time','takt time','bottleneck'],'engineering change':['ECN','BOM impact','effectivity date'],'quality issue':['root cause','quality gate','PPAP status'],'launch readiness':['APQP deliverables','SOP milestone','manufacturing readiness'],'prototype build':['pilot build','drawing release','validation plan'],'material shortage':['inventory coverage','alternate part','shortage risk'],'free conversation':['milestone','owner','due date']}[t]||['risk','owner','due date'])}function speak(t,r=.95){if(!speechSynthesis)return;speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.lang='en-US';u.rate=r;let a=speechSynthesis.getVoices();u.voice=a.find(v=>/Samantha|Ava|Allison|Susan|Zira|Jenny|Aria/i.test(v.name)&&v.lang.startsWith('en-US'))||a.find(v=>v.lang.startsWith('en-US'))||null;speechSynthesis.speak(u)}function recognize(cb){let R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return toast('Voice recognition unavailable');let r=new R();r.lang='en-US';r.onresult=e=>cb(e.results[0][0].transcript);r.start()}function score(t){let a=target.textContent.toLowerCase().replace(/[^a-z0-9 ]/g,'').split(/ +/),b=t.toLowerCase().replace(/[^a-z0-9 ]/g,'').split(/ +/),n=a.filter(x=>b.includes(x)).length;result.innerHTML=`Recognized: <b>${esc(t)}</b><br>Word match: <b>${Math.round(n/a.length*100)}%</b>`}function toast(t){let x=q('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2000)}if('serviceWorker'in navigator)navigator.serviceWorker.register('service-worker.js');nav();go('home');
